CREATE FUNCTION public.set_access(_user uuid,_level text,_area text,_position text,_sales boolean,_status text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old public.user_access; BEGIN IF NOT(public.is_partner(auth.uid()) OR public.access_level_for(auth.uid())='gerentes') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO old FROM public.user_access WHERE user_id=_user FOR UPDATE; IF NOT public.is_partner(auth.uid()) AND (_level='socios' OR old.access_level='socios') THEN RAISE EXCEPTION 'Apenas sócios podem gerir acesso de sócios'; END IF; IF _user=auth.uid() THEN RAISE EXCEPTION 'Não pode alterar o seu próprio acesso'; END IF; IF _status<>'ativo' AND length(trim(coalesce(_reason,'')))<3 THEN RAISE EXCEPTION 'Justificação obrigatória'; END IF; INSERT INTO public.user_access(user_id,access_level,area,position,sales_enabled,status) VALUES(_user,_level,_area,_position,_sales AND _level='funcionario',_status) ON CONFLICT(user_id) DO UPDATE SET access_level=excluded.access_level,area=excluded.area,position=excluded.position,sales_enabled=excluded.sales_enabled,status=excluded.status,updated_at=now(); INSERT INTO public.audit_events(actor_id,action,target_id,details) VALUES(auth.uid(),'acesso',_user,jsonb_build_object('level',_level,'status',_status,'reason',_reason)); END $$;
CREATE FUNCTION public.prepare_payroll(_period date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.employees; deduction numeric; BEGIN IF NOT public.area_access(auth.uid(),'rh') THEN RAISE EXCEPTION 'Sem permissão'; END IF; FOR e IN SELECT * FROM public.employees LOOP SELECT count(*)*e.base_salary/30 INTO deduction FROM public.absences a WHERE a.employee_id=e.id AND a.decision<>'aprovada' AND (a.submitted_at IS NOT NULL OR now()>a.occurred_at+interval '48 hours') AND date_trunc('month',a.absence_date + CASE WHEN extract(day FROM a.absence_date)>=10 THEN interval '1 month' ELSE interval '0 months' END)::date=date_trunc('month',_period)::date; INSERT INTO public.payroll_runs(period,employee_id,base,absence_deduction,inss_worker,inss_employer,union_deduction) VALUES(date_trunc('month',_period)::date,e.id,e.base_salary,deduction,greatest(0,e.base_salary-deduction)*.03,greatest(0,e.base_salary-deduction)*.04,CASE WHEN e.union_member THEN greatest(0,e.base_salary-deduction)*e.union_pct/100 ELSE 0 END) ON CONFLICT(period,employee_id) DO NOTHING; END LOOP; END $$;
CREATE FUNCTION public.sign_payroll_hr(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.area_access(auth.uid(),'rh') THEN RAISE EXCEPTION 'Sem permissão'; END IF; UPDATE public.payroll_runs SET status='processado',hr_signed_by=auth.uid(),hr_signed_at=now() WHERE id=_id AND status='rascunho' AND irps IS NOT NULL AND net IS NOT NULL AND net>=0; IF NOT FOUND THEN RAISE EXCEPTION 'IRPS oficial não validado; folha não pode ser emitida'; END IF; END $$;
CREATE FUNCTION public.pay_payroll(_id uuid,_amount numeric,_proof text,_reason text,_event uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.payroll_runs; paid numeric; BEGIN IF NOT public.area_access(auth.uid(),'financas') THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM public.payroll_runs WHERE id=_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.payroll_payments WHERE event_key=_event) THEN RETURN; END IF; SELECT coalesce(sum(amount),0) INTO paid FROM public.payroll_payments WHERE run_id=_id; IF r.status NOT IN ('processado','parcial') OR _amount<=0 OR _amount>r.net-paid THEN RAISE EXCEPTION 'Valor ou estado inválido'; END IF; IF _amount<r.net-paid AND length(trim(coalesce(_reason,'')))<3 THEN RAISE EXCEPTION 'Justifique o pagamento parcial'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='comprovativos' AND name=_proof AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Comprovativo obrigatório'; END IF; INSERT INTO public.payroll_payments(run_id,amount,proof_path,reason,paid_by,event_key) VALUES(_id,_amount,_proof,_reason,auth.uid(),_event); UPDATE public.payroll_runs SET status=CASE WHEN paid+_amount=r.net THEN 'pago' ELSE 'parcial' END WHERE id=_id; INSERT INTO public.audit_events(actor_id,action,target_id,details) VALUES(auth.uid(),'pagamento_salario',_id,jsonb_build_object('amount',_amount)); END $$;
CREATE FUNCTION public.sign_payroll_employee(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.payroll_runs r SET employee_signed_by=auth.uid(),employee_signed_at=now(),status='confirmado' WHERE r.id=_id AND r.status='pago' AND r.hr_signed_at IS NOT NULL AND EXISTS(SELECT 1 FROM public.employees e WHERE e.id=r.employee_id AND e.user_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Recibo não disponível para confirmação'; END IF; END $$;
CREATE FUNCTION public.cast_resolution_vote(_id uuid,_vote text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.shareholders; r public.resolutions; favor numeric; contra numeric; result text; BEGIN IF NOT public.is_partner(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM public.resolutions WHERE id=_id FOR UPDATE; SELECT * INTO s FROM public.shareholders WHERE user_id=auth.uid(); IF s.id IS NULL OR r.status<>'aberta' OR _vote NOT IN ('favor','contra','veto') OR (_vote='veto' AND NOT s.founder) THEN RAISE EXCEPTION 'Voto inválido ou sócio não associado'; END IF; INSERT INTO public.resolution_votes(resolution_id,shareholder_id,vote) VALUES(_id,s.id,_vote) ON CONFLICT(resolution_id,shareholder_id) DO UPDATE SET vote=excluded.vote; SELECT coalesce(sum(sh.capital_pct) FILTER(WHERE v.vote='favor'),0),coalesce(sum(sh.capital_pct) FILTER(WHERE v.vote<>'favor'),0) INTO favor,contra FROM public.resolution_votes v JOIN public.shareholders sh ON sh.id=v.shareholder_id WHERE v.resolution_id=_id; result:='aberta'; IF EXISTS(SELECT 1 FROM public.resolution_votes v JOIN public.shareholders sh ON sh.id=v.shareholder_id WHERE v.resolution_id=_id AND v.vote='veto' AND sh.founder) THEN result:='rejeitada'; ELSIF (r.qualified_quorum AND favor>=70) OR (NOT r.qualified_quorum AND favor>50) THEN result:='aprovada'; ELSIF (r.qualified_quorum AND contra>30) OR (NOT r.qualified_quorum AND contra>=50) THEN result:='rejeitada'; END IF; UPDATE public.resolutions SET status=result WHERE id=_id; END $$;
CREATE FUNCTION public.validate_new_proof() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='comprovativos' AND name=NEW.proof_path AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Comprovativo obrigatório'; END IF; RETURN NEW; END $$;
ALTER TABLE public.sales ADD COLUMN proof_path text;
CREATE TRIGGER sale_proof_required BEFORE INSERT ON public.sales FOR EACH ROW EXECUTE FUNCTION public.validate_new_proof();
CREATE TRIGGER movement_proof_required BEFORE INSERT ON public.cash_movements FOR EACH ROW EXECUTE FUNCTION public.validate_new_proof();
CREATE FUNCTION public.validate_debt_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE debt numeric; paid numeric; BEGIN SELECT amount INTO debt FROM public.debts WHERE id=NEW.debt_id FOR UPDATE; SELECT coalesce(sum(amount),0) INTO paid FROM public.debt_payments WHERE debt_id=NEW.debt_id; IF NEW.amount<=0 OR NEW.amount>debt-paid THEN RAISE EXCEPTION 'Pagamento acima do saldo ou inválido'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='comprovativos' AND name=NEW.proof_path AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Comprovativo obrigatório'; END IF; RETURN NEW; END $$;
CREATE TRIGGER debt_payment_validation BEFORE INSERT ON public.debt_payments FOR EACH ROW EXECUTE FUNCTION public.validate_debt_payment();
REVOKE ALL ON FUNCTION public.set_access(uuid,text,text,text,boolean,text,text), public.prepare_payroll(date),public.sign_payroll_hr(uuid),public.pay_payroll(uuid,numeric,text,text,uuid),public.sign_payroll_employee(uuid),public.cast_resolution_vote(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_access(uuid,text,text,text,boolean,text,text), public.prepare_payroll(date),public.sign_payroll_hr(uuid),public.pay_payroll(uuid,numeric,text,text,uuid),public.sign_payroll_employee(uuid),public.cast_resolution_vote(uuid,text) TO authenticated;
DROP POLICY "profiles self or gestao" ON public.profiles;
CREATE POLICY "profiles authorized reads" ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_gestao(auth.uid()) OR public.area_access(auth.uid(),'rh'));
CREATE POLICY "finance sales read" ON public.sales FOR SELECT TO authenticated USING(public.area_access(auth.uid(),'financas'));
CREATE POLICY "finance projects read" ON public.projects FOR SELECT TO authenticated USING(public.area_access(auth.uid(),'financas'));
CREATE POLICY "marketing projects" ON public.projects FOR ALL TO authenticated USING(public.access_level_for(auth.uid())='marketing' AND area=(SELECT a.area FROM public.user_access a WHERE a.user_id=auth.uid())) WITH CHECK(public.access_level_for(auth.uid())='marketing' AND area=(SELECT a.area FROM public.user_access a WHERE a.user_id=auth.uid()));